BIN_PATH = "/app/admin-tool"
OUT_PATH = "/app/output.txt"


def parse_int_token(tok):
    tok = tok.strip()
    if not tok:
        raise ValueError("empty token")
    # strip trailing comments already handled by caller
    # handle byte('x') / byte("x") wrappers -> extract inner
    m = re.search(r"""^byte\s*\(\s*(.+)\s*\)$""", tok)
    if m:
        tok = m.group(1).strip()
    # char literal: 'A' or '\x41' or '\n' etc.
    if len(tok) >= 3 and tok[0] == "'" and tok[-1] == "'":
        inner = tok[1:-1]
        # decode Go char literal escapes (subset sufficient for single byte keys)
        try:
            # python unicode_escape handles \x, \n, \\, etc.
            decoded = inner.encode("utf-8").decode("unicode_escape").encode("latin1")
            if len(decoded) == 1:
                return decoded[0]
        except Exception:
            pass
        if len(inner) == 1:
            return ord(inner)
        raise ValueError(f"bad char literal {tok!r}")
    # rune / string literal "..." single char? treat as char
    if len(tok) >= 3 and tok[0] == '"' and tok[-1] == '"':
        inner = tok[1:-1]
        try:
            decoded = inner.encode("utf-8").decode("unicode_escape").encode("latin1")
            if len(decoded) == 1:
                return decoded[0]
        except Exception:
            pass
        raise ValueError(f"bad string literal {tok!r}")
    return int(tok, 0) & 0xFF


def is_printable_cred(bs):
    if not bs or len(bs) < 2 or len(bs) > 256:
        return False
    # credentials are expected to be printable ASCII (no spaces at ends ideally)
    # allow 33..126 plus allow nothing else; be slightly lenient: allow all 32..126
    for b in bs:
        if b < 32 or b > 126:
            return False
    return True


def find_byte_arrays(text):
    """Find all []byte{...} style literals generically (no var-name assumptions)."""
    arrays = []  # list of dicts {var, bytes, pos}
    # Pattern covers: []byte{...}, [...]byte{...}, [N]byte{...}
    pat = re.compile(
        r"\[\s*(?:\.\.\.)?\s*\d*\s*\]\s*byte\s*\{\s*(?P<body>[^}]*?)\s*\}",
        re.DOTALL,
    )
    for m in pat.finditer(text):
        body = m.group("body").strip()
        if not body:
            continue
        # split on commas; also handle newlines
        raw_parts = [p for p in body.split(",")]
        vals = []
        ok = True
        for p in raw_parts:
            # strip line comments
            p = p.split("//")[0].strip()
            if not p:
                continue
            # each element should be a single integer (hex/dec) possibly wrapped
            # extract the numeric/char token
            tm = re.search(
                r"""byte\s*\(\s*(?:0[xX][0-9a-fA-F]+|\d+|'.+?')\s*\)|0[xX][0-9a-fA-F]+|\d+|'.+?'|\"(?:[^\"\\]|\\.)*\"""",
                p,
            )
            if not tm:
                ok = False
                break
            try:
                vals.append(parse_int_token(tm.group(0)))
            except Exception:
                ok = False
                break
        if not ok or len(vals) < 3:
            continue
        # try to recover a variable name for diagnostics/mapping (best effort)
        prefix = text[max(0, m.start() - 300): m.start()]
        varname = None
        # look for the nearest "NAME := ...", "NAME = ...", "var NAME ... =" on preceding text
        # take the last such match
        for vm in re.finditer(
            r"(?:var\s+)?(?P<name>[A-Za-z_]\w*)\s*(?:\[\s*(?:\.\.\.)?\s*\d*\s*\]\s*byte\s*)?\s*:?=\s*(?:\[\s*(?:\.\.\.)?\s*\d*\s*\]\s*byte\s*)?\s*$",
            prefix.strip().split("\n")[-1] if prefix.strip().split("\n") else "",
        ):
            varname = vm.group("name")
        if varname is None:
            # fallback: last identifier before the literal
            ids = re.findall(r"[A-Za-z_]\w*", prefix)
            # skip keywords
            skip = {"var", "const", "byte", "string", "func", "return", "for",
                    "range", "if", "else", "package", "import", "flag", "fmt", "os"}
            for cand in reversed(ids):
                if cand not in skip:
                    varname = cand
                    break
        if varname is None:
            varname = f"array_{m.start()}"
        arrays.append({"var": varname, "bytes": bytes(vals), "pos": m.start()})

    # Also handle []byte("...escaped...") form: byte slice from string literal
    for m in re.finditer(r"\[\]\s*byte\s*\(\s*\"(?P<s>(?:[^\"\\]|\\.)*)\"\s*\)", text):
        raw = m.group("s")
        try:
            decoded = raw.encode("utf-8").decode("unicode_escape").encode("latin1")
        except Exception:
            continue
        if len(decoded) < 3:
            continue
        prefix = text[max(0, m.start() - 300): m.start()]
        ids = re.findall(r"[A-Za-z_]\w*", prefix)
        varname = ids[-1] if ids else f"strarray_{m.start()}"
        arrays.append({"var": varname, "bytes": bytes(decoded), "pos": m.start()})
    arrays.sort(key=lambda d: d["pos"])
    return arrays


def find_candidate_keys(text):
    """Collect candidate single-byte keys without assuming a variable name."""
    cands = []  # list of (name_or_None, value, priority)
    # identifiers referenced in an XOR expression are high priority
    xor_ids = set(re.findall(r"\^\s*([A-Za-z_]\w*)", text))
    xor_ids |= set(re.findall(r"([A-Za-z_]\w*)\s*\^", text))
    # keywords / builtin types that can appear around ^ but are not keys
    skip_ids = {"byte", "uint8", "int", "uint", "string", "len", "cap", "nil",
                "true", "false", "i", "j", "b", "v", "out", "data", "b2"}

    # generic single-value assignments: NAME [=|:=] <int>  (hex/dec/char)
    # scan line by line to be spacing-robust
    for m in re.finditer(
        r"(?P<name>[A-Za-z_]\w*)\s*(?::=|=)\s*(?P<val>byte\s*\(\s*(?:0[xX][0-9a-fA-F]+|\d+|'.+?')\s*\)|0[xX][0-9a-fA-F]+|\d+|'.+?')",
        text,
    ):
        name = m.group("name")
        if name in {"package", "import", "func", "return", "if", "for", "switch"}:
            continue
        try:
            v = parse_int_token(m.group("val"))
        except Exception:
            continue
        if 1 <= v <= 255:
            prio = 10 if name in xor_ids else 0
            cands.append((name, v, prio))

    # var/const declarations with explicit type: var NAME byte = 0x..
