        r"(?:var|const)\s+(?P<name>[A-Za-z_]\w*)\s+(?:byte|uint8|int|uint)?\s*=\s*(?P<val>byte\s*\(\s*(?:0[xX][0-9a-fA-F]+|\d+|'.+?')\s*\)|0[xX][0-9a-fA-F]+|\d+|'.+?')",
        text,
    ):
        name = m.group("name")
        try:
            v = parse_int_token(m.group("val"))
        except Exception:
            continue
        if 1 <= v <= 255:
            prio = 10 if name in xor_ids else 0
            cands.append((name, v, prio))

    # XOR with an inline constant:  b ^ 0x2A   -> constant is the key
    for m in re.finditer(r"\^\s*(?P<val>0[xX][0-9a-fA-F]+|\d+)", text):
