def va_to_file_offset(data, va):
    e_phoff = struct.unpack("<Q", data[0x20:0x28])[0]
    e_phentsize = struct.unpack("<H", data[0x36:0x38])[0]
    e_phnum = struct.unpack("<H", data[0x38:0x3A])[0]
    for i in range(e_phnum):
        off = e_phoff + i * e_phentsize
        (p_type, p_flags, p_offset, p_vaddr, p_paddr,
         p_filesz, p_memsz, p_align) = struct.unpack("<IIQQQQQQ", data[off:off + 56])
        if p_type != 1:
            continue
        if p_vaddr <= va < p_vaddr + max(p_filesz, p_memsz):
            return va - p_vaddr + p_offset
    return None


def read_cstring_at_va(data, va, length):
    off = va_to_file_offset(data, va)
    if off is None or off < 0 or off + length > len(data):
        return None
    return data[off: off + length]


def get_disasm(bin_path):
    # Prefer `go tool objdump` (shows main.main with source lines); fallback to objdump.
    for cmd in (["go", "tool", "objdump", "-s", "main.main", bin_path],
                ["objdump", "-d", "--disassemble", bin_path]):
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if p.returncode == 0 and p.stdout and "main.main" in p.stdout:
                return p.stdout
        except Exception:
            continue
    return ""


